parameters.jsCode:
// The period, as a half-open interval [start, end).
//
// Half-open, not inclusive, and that is not pedantry: with an inclusive end
// date a post published at 23:30 on the last of the month lands in both
// periods or neither depending on the timezone the comparison happens in.
// [start, end) has exactly one answer.
//
// UTC throughout. The workflow timezone is Europe/Madrid so the trigger
// fires at a sensible local hour, but the boundary itself must not move
// twice a year with daylight saving.
const now = new Date();
const end = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), 1));
const start = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth() - 1, 1));

return [{ json: {
  period_start: start.toISOString().slice(0, 10),
  period_end: end.toISOString().slice(0, 10),
} }];

// The circuit breaker on the money.
//
// Everything upstream is idempotent, which protects against paying twice. It
// does not protect against paying the right number of times for the wrong
// amount -- a provider changing view counts from units to thousands, a
// tracking code collision, a migration that dropped a WHERE clause. Those
// produce one clean, correct-looking, catastrophically large run.
//
// So this compares against last month and refuses to look away if the total
// moved more than it plausibly could. Refusing is the cheap outcome: the
// rows are already written, nothing is transferred by this workflow, and a
// human looks at a number in the morning. The expensive outcome is the
// alternative.

const MULTIPLIER = Number($env.PAYOUT_SANITY_MULTIPLIER ?? 3);
const CEILING_CENTS = Number($env.PAYOUT_CEILING_CENTS ?? 500000);

const rows = $input.all().map(i => i.json);
const total = rows.reduce((s, r) => s + Number(r.amount_cents), 0);
const creators = rows.length;

const prev = $('Previous period total').first().json;
const prevTotal = Number(prev.total_cents ?? 0);
const period = $('Period').first().json;

const reasons = [];
if (total > CEILING_CENTS) {
  reasons.push(`total ${total} cents is above the absolute ceiling ${CEILING_CENTS}`);
}
// Only compares when there is something to compare to. The first month ever,
// and any month after a gap, has prevTotal 0 and must not be held on the
// strength of a division by nothing.
if (prevTotal > 0 && total > prevTotal * MULTIPLIER) {
  reasons.push(`total ${total} cents is more than ${MULTIPLIER}x last period's ${prevTotal}`);
}

return [{ json: {
  ...period,
  creators,
  total_cents: total,
  previous_total_cents: prevTotal,
  change_ratio: prevTotal > 0 ? Number((total / prevTotal).toFixed(2)) : null,
  sane: reasons.length === 0,
  reason: reasons.join('; ') || 'within expected bounds',
  largest: rows.slice().sort((a, b) => b.amount_cents - a.amount_cents)[0] ?? null,
} }];

